'use strict';
function ratingStars(rating){return `<span class="rating-stars" role="img" aria-label="${rating} trên 5 sao"><span aria-hidden="true">★★★★★</span><span class="rating-stars-fill" style="width:${Math.max(0,Math.min(5,rating))*20}%" aria-hidden="true">★★★★★</span></span>`;}
function demoRatingHTML(t){return `<span class="demo-rating">${ratingStars(t.demoRating)} <b>${t.demoRating.toFixed(1)}/5</b><span>· ${t.demoReviewCount} đánh giá mô phỏng</span></span>`;}
function tourCardHTML(t){
  const esc=escapeHTML;
  const placesRoute=t.places.map(esc).join(' <span class="loc-arrow" aria-hidden="true">→</span> ');
  const tagsBadges=t.tags.map(tag=>`<button type="button" class="tag-badge" data-filter-tag="${esc(tag)}" title="Lọc theo chủ đề: ${esc(tag)}">${esc(tag)}</button>`).join('');
  return `<article class="tour-card"><div class="tour-image"><img src="assets/${t.image}" alt="${esc(t.imageCaption)}" loading="lazy"><span class="pill">${esc(t.label)}</span><button class="heart" data-favorite="${t.id}" aria-label="Lưu tour ${esc(t.name)}" aria-pressed="${favorites.includes(t.id)}">${favorites.includes(t.id)?'♥':'♡'}</button><span class="duration-badge">◷ ${t.days} ngày${t.nights?' '+t.nights+' đêm':''}</span></div><div class="card-content"><div class="location tour-location" aria-label="Địa điểm: ${t.places.map(esc).join(' → ')}"><span class="location-pin-wrapper"><svg class="location-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 0 1 0-5 2.5 2.5 0 0 1 0 5z"/></svg><span class="location-title">Điểm đến:</span></span><span class="location-places">${placesRoute}</span></div><h3><a href="#tour-${t.id}" data-tour="${t.id}">${esc(t.name)}</a></h3>${demoRatingHTML(t)}<div class="card-tags" aria-label="Chủ đề tour">${tagsBadges}</div><p class="card-summary">${esc(t.summary)}</p><ul class="card-highlights">${t.cardHighlights.map(h=>`<li><span aria-hidden="true">✓</span> ${esc(h)}</li>`).join('')}</ul><div class="card-services" aria-label="Dịch vụ dự kiến">${t.serviceBadges.map(s=>`<span>${esc(s)}</span>`).join('')}</div><p class="card-origin">Khởi hành từ Thái Nguyên · Đoàn riêng</p><div class="card-bottom"><span class="price"><small>Dự kiến từ / người lớn</small>${money(t.price)}</span><button class="card-detail-button" data-tour="${t.id}">Xem tour <span aria-hidden="true">↗</span></button></div></div></article>`;
}
function demoReviewCardHTML(r){const esc=escapeHTML;const initials=r.name.trim().split(/\s+/).slice(-2).map(s=>s[0]).join('');return `<article class="tour-review-card"><div class="review-person"><span class="avatar">${esc(initials)}</span><div><b>${esc(r.name)}</b><small>${esc(r.party)}</small></div><span class="demo-label">Mô phỏng</span></div><div class="review-score">${ratingStars(r.rating)} <span>${r.rating}/5</span></div><h4>${esc(r.title)}</h4><p>${esc(r.body)}</p></article>`;}
function tourReviewCards(t,stars){const matches=t.demoReviews.filter(r=>!stars||r.rating===stars);return matches.length?matches.map(demoReviewCardHTML).join(''):'<p class="review-empty">Chưa có đánh giá mô phỏng ở mức sao này. Chọn “Tất cả” để xem các nhận xét.</p>';}
function tourReviewsHTML(t){const categories=[['guide','Hướng dẫn & hỗ trợ'],['planning','Lịch trình & trải nghiệm'],['value','Dịch vụ & giá trị']];return `<section class="tour-customer-reviews" id="tour-feedback"><p class="eyebrow">GÓC NHÌN VỀ HÀNH TRÌNH</p><h3>Đánh giá về tour & dịch vụ</h3><p class="review-disclosure">${escapeHTML(t.demoReviewDisclosure)}</p><div class="review-dashboard"><div class="review-overall"><strong>${t.demoRating.toFixed(1)}</strong><span>/ 5</span><div>${ratingStars(t.demoRating)}</div><small>${t.demoReviewCount} đánh giá mô phỏng</small></div><div class="review-categories">${categories.map(([key,label])=>{const score=t.demoReviews.reduce((sum,r)=>sum+r.scores[key],0)/t.demoReviews.length;return `<div><span>${label}</span><b>${score.toFixed(1)}</b><div class="score-track"><span style="width:${score*20}%"></span></div></div>`;}).join('')}</div></div><div class="review-filters" role="group" aria-label="Lọc đánh giá mô phỏng theo số sao">${[0,5,4,3,2,1].map(stars=>`<button type="button" data-review-stars="${stars}" aria-pressed="${stars===0}">${stars?stars+' sao':'Tất cả'} <span>(${t.demoReviews.filter(r=>!stars||r.rating===stars).length})</span></button>`).join('')}</div><div id="tour-review-list" class="tour-review-list" aria-live="polite">${tourReviewCards(t,0)}</div></section>`;}
function tourQuickFactsHTML(t){return `<div class="experience-facts"><div><span>◷</span><small>THỜI GIAN</small><b>${t.days} ngày${t.nights?' '+t.nights+' đêm':''}</b></div><div><span><svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" style="vertical-align:middle;color:#d84534;margin-bottom:2px" aria-hidden="true"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 0 1 0-5 2.5 2.5 0 0 1 0 5z"/></svg></span><small>HÀNH TRÌNH</small><b>${t.places.length} điểm đến</b></div><div><span>❧</span><small>PHONG CÁCH</small><b>${escapeHTML(t.tags.slice(0,2).join(' · '))}</b></div><div><span>↗</span><small>KHỞI HÀNH</small><b>Thái Nguyên</b></div></div><nav class="tour-section-nav" aria-label="Nội dung tour">${[['tour-overview','Giới thiệu'],['tour-itinerary','Lịch trình'],['tour-services','Dịch vụ'],['tour-feedback','Đánh giá']].map(([id,name])=>`<button type="button" data-tour-section="${id}">${name}</button>`).join('')}</nav>`;}
function bindTourEngagement(t){$('#modal-content').querySelectorAll('[data-review-stars]').forEach(b=>b.onclick=()=>{const stars=Number(b.dataset.reviewStars);$('#tour-review-list').innerHTML=tourReviewCards(t,stars);$('#modal-content').querySelectorAll('[data-review-stars]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});$('#modal-content').querySelectorAll('[data-tour-section]').forEach(b=>b.onclick=()=>{const target=document.getElementById(b.dataset.tourSection);target.scrollIntoView({behavior:'smooth',block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});}
function demoReviewsMarkdown(t){return `\n\n## Đánh giá mô phỏng\n\n${t.demoReviewDisclosure}\n\nĐiểm trung bình mô phỏng: ${t.demoRating}/5 (${t.demoReviewCount} nhận xét).\n\n${t.demoReviews.map(r=>`### ${r.name} — ${r.rating}/5 — ${r.party} (mô phỏng)\n\n**${r.title}**\n\n${r.body}`).join('\n\n')}\n`;}
